/* Sayısal soru üreticileri: her çağrıda yeni sayılar. Doğru cevap ilk şık. */
const r = (a, b, s = 1) => a + Math.floor(Math.random() * ((b - a) / s + 1)) * s;
const f = (x, d = 2) => { const v = +x.toFixed(d); return String(v).replace('.', ','); };
const uniq = (arr) => {
  const out = []; arr.forEach(x => { if (!out.includes(x)) out.push(x); });
  // çakışan şıklar yüzünden 5'ten az kaldıysa doğru cevaptan türetilmiş çeldiricilerle tamamla
  const m = String(out[0]).match(/^(−|-)?[\d.,]+/);
  if (m) {
    const neg = /^(−|-)/.test(out[0]), num = parseFloat(m[0].replace(/^(−|-)/, '').replace(',', '.')), rest = String(out[0]).slice(m[0].length);
    const mk = v => (neg ? '−' : '') + String(+v.toFixed(4)).replace('.', ',') + rest;
    for (const k of [2, 0.5, 10, 0.1, 1.5, 3, 0.25, 4]) { if (out.length >= 5) break; const s = num === 0 ? mk(k) : mk(num * k); if (!out.includes(s)) out.push(s); }
  }
  return out.slice(0, 5);
};
const GEN = [
  { k: 'k1', g() { const V = r(6, 48, 6), R = r(2, 12); const I = V / R; return { q: `${V} V’luk kaynağa ${R} Ω’luk direnç bağlanıyor. Çekilen güç kaç W’tır?`, o: uniq([f(V * I), f(I), f(V * R), f(V / I), f(I * I)]), e: `I = ${V}/${R} = ${f(I)} A; P = V·I = ${f(V * I)} W.` }; } },
  { k: 'k1', g() { const P = r(500, 3000, 100), e = r(70, 95, 5); return { q: `${P} W elektriksel güç çeken motorun verimi %${e}. Isıya dönüşen güç kaç W’tır?`, o: uniq([f(P * (100 - e) / 100), f(P * e / 100), f(P), f(e), f(P / e)]), e: `Kayıp = ${P} × (1 − ${e / 100}) = ${f(P * (100 - e) / 100)} W.` }; } },
  { k: 'k2', g() { const I = r(10, 40, 5), R = [0.1, 0.2, 0.25, 0.5][r(0, 3)]; return { q: `${I} A çeken bir devrede gevşek bağlantı ${f(R)} Ω direnç geliştirdi. Bağlantıda ısıya dönüşen güç kaç W’tır?`, o: uniq([f(I * I * R), f(I * R), f(I / R), f(I * I / R), f(I * R * R)]), e: `P = I²R = ${I}² × ${f(R)} = ${f(I * I * R)} W.` }; } },
  { k: 'k2', g() { const H = [8, 12, 16, 20, 24][r(0, 4)]; return { q: `${H} ft yüksekliğe dayanan düz merdivenin tabanı yapıdan kaç ft uzakta olmalıdır?`, o: uniq([f(H / 4), f(H / 2), f(H / 3), f(3), f(H / 6)]), e: `Taban = yükseklik / 4 = ${f(H / 4)} ft (≈76°).` }; } },
  { k: 'k3', g() { const n = r(2, 9) * 1000; return { q: `${n} elektronun toplam yükü kaç coulomb’dur?`, o: uniq([`−${f(n * 1.602e-19 * 1e16, 3)} × 10⁻¹⁶`, `+${f(n * 1.602e-19 * 1e16, 3)} × 10⁻¹⁶`, `−${f(n * 1.602e-19 * 1e19, 3)} × 10⁻¹⁹`, `−${f(n / 1.602, 2)} × 10¹⁹`, `−${f(n * 6.24e-18 * 1e15, 2)} × 10⁻¹⁵`]), e: `q = n·e = ${n} × (−1,602×10⁻¹⁹) C.` }; } },
  { k: 'k3', g() { const I = r(1, 5), t = r(5, 30, 5), W = r(1, 6) * 600; const q = I * t; return { q: `Bir ampulden ${t} s boyunca ${I} A akım geçiyor ve ${W} J enerji yayılıyor. Ampuldeki gerilim düşümü kaç V’tur?`, o: uniq([f(W / q), f(W * q), f(W / I), f(W / t), f(q / W, 4)]), e: `Δq = ${I}×${t} = ${q} C; v = ${W}/${q} = ${f(W / q)} V.` }; } },
  { k: 'k4', g() { const P = r(40, 200, 20), h = r(1, 6); return { q: `${P} W’lık bir lamba ${h} saat çalışıyor. Tükettiği enerji kaç kJ’dür?`, o: uniq([f(P * h * 3600 / 1000), f(P * h), f(P * h * 60 / 1000), f(P * h / 1000), f(P * 3600 / 1000)]), e: `w = ${P} × ${h} × 3600 = ${P * h * 3600} J.` }; } },
  { k: 'k4', g() { const V = [120, 220, 240][r(0, 2)], I = r(5, 20), W = r(1, 9) * 36000; const p = V * I; return { q: `${V} V hatta ${I} A çeken ocak ${W / 1000} kJ enerji tüketene kadar kaç saniye geçer?`, o: uniq([f(W / p), f(p / W, 4), f(W / V), f(W / I), f(W * p / 1e6)]), e: `p = ${p} W; t = ${W}/${p} = ${f(W / p)} s.` }; } },
  { k: 'k4', g() { const v = r(2, 12), i = r(1, 6), plus = Math.random() < 0.5; const p = (plus ? 1 : -1) * v * i; return { q: `${v} V’luk bir elemana ${i} A akım ${plus ? '(+)' : '(−)'} terminalinden giriyor. Pasif işaret kabulüne göre eleman için hangisi doğrudur?`, o: uniq([`${p} W, ${p > 0 ? 'güç yutar' : 'güç sağlar'}`, `${-p} W, ${-p > 0 ? 'güç yutar' : 'güç sağlar'}`, `${p} W, ${p > 0 ? 'güç sağlar' : 'güç yutar'}`, `${v + i} W, güç yutar`, `0 W`]), e: `p = ${plus ? '+' : '−'}vi = ${p} W.` }; } },
  { k: 'k6', g() { const ex = r(12, 16), kv = r(10, 40, 5); const i = 1.6e-19 * Math.pow(10, ex), p = kv * 1000 * i; const fp = x => x >= 1 ? f(x) + ' W' : f(x * 1000, 3) + ' mW'; return { q: `Saniyede 10^${ex} elektron taşıyan CRT demeti ${kv} kV ile hızlandırılıyor. Demet gücü?`, o: uniq([fp(p), fp(p * 10), fp(p / 10), fp(p * 1000), fp(i)]), e: `i = 1,6×10⁻¹⁹ × 10^${ex} = ${i.toExponential(1)} A; p = V₀·i = ${fp(p)}.` }; } },
  { k: 'k8', g() { const L = r(1, 9), d = [0.5, 1, 2][r(0, 2)]; const A = Math.PI * Math.pow(d / 1000, 2) / 4, R = 1.72e-8 * L / A; return { q: `${L} m uzunluğunda, ${f(d)} mm çaplı bakır telin (ρ = 1,72×10⁻⁸ Ω·m) direnci yaklaşık kaç Ω’dur?`, o: uniq([f(R, 4), f(R * 2, 4), f(R / 2, 4), f(R * 4, 4), f(R / 4, 4)]), e: `A = π(${f(d)}×10⁻³)²/4; R = ρℓ/A = ${f(R, 4)} Ω. Çap 2 katına çıkarsa A 4 kat → R 4’te bir.` }; } },
  { k: 'k8', g() { const V = r(5, 60, 5), k = r(1, 20); const i = V / k; return { q: `${V} V gerilim kaynağına ${k} kΩ direnç bağlanıyor. Dirençte harcanan güç kaç mW’tır?`, o: uniq([f(V * i), f(i), f(V * V * k), f(V / i), f(i * i * k)]), e: `i = ${f(i)} mA; p = V·i = ${f(V * i)} mW.` }; } },
  { k: 'k9', g() { const b = r(4, 12), n = r(2, Math.min(b - 1, 7)); return { q: `Bir devrede ${b} dal ve ${n} düğüm var. Bağımsız çevre sayısı kaçtır?`, o: uniq([String(b - n + 1), String(b + n - 1), String(b - n), String(b - n + 2), String(n - 1)]), e: `l = b − n + 1 = ${b} − ${n} + 1 = ${b - n + 1}.` }; } },
  { k: 'k10', g() { const a = r(1, 9), b = r(1, 9), c = r(1, 9); const d = a + b - c; return { q: `Bir düğüme ${a} A ve ${b} A giriyor, ${c} A çıkıyor. Dördüncü koldan çıkan akım kaç A’dir?`, o: uniq([String(d), String(a + b + c), String(a - b + c), String(c - a - b + 2 * c), String(-d)]), e: `Giren = çıkan: ${a} + ${b} = ${c} + i₄ → i₄ = ${d} A${d < 0 ? ' (negatif: aslında giriyor)' : ''}.` }; } },
  { k: 'k10', g() { const Vs = r(10, 60, 5), R1 = r(1, 9), R2 = r(1, 9); const i = Vs / (R1 + R2); return { q: `Tek çevreli devrede ${Vs} V kaynak, ${R1} Ω ve ${R2} Ω seri. ${R1} Ω’daki gerilim düşümü kaç V’tur?`, o: uniq([f(i * R1), f(i * R2), f(i), f(Vs), f(Vs / R1)]), e: `KVL: ${Vs} = (${R1} + ${R2})i → i = ${f(i)} A; v₁ = ${f(i * R1)} V.` }; } }
];
